{
  "name": "cloud-resume",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@types/react": "^18.3.3",
    "@types/react-dom": "^18.3.0",
    "@vitejs/plugin-react": "^4.3.1",
    "typescript": "^5.5.4",
    "vite": "^5.4.2"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

:root {
  font-family: Inter, system-ui, sans-serif;
  color: #e2e8f0;
  background: #0f172a;
}

body {
  margin: 0;
}

export const profile = {
  name: 'Deonarayan',
  title: 'Cloud DevOps Engineer',
  summary: 'Building reliable delivery pipelines and cloud infrastructure.',
};

import { profile } from '../content/profile';

export default function Hero() {
  return (
    <header>
      <h1>{profile.name}</h1>
      <p>{profile.title}</p>
    </header>
  );
}

import Hero from './components/Hero';

export default function App() {
  return (
    <main className="container">
      <Hero />
    </main>
  );
}

export const profile = {
  name: 'Deonarayan',
  title: 'Cloud DevOps Engineer',
  location: 'Remote',
  summary:
    'Cloud DevOps engineer focused on CI/CD automation, Kubernetes delivery, and infrastructure as code across Azure and AWS.',
  email: 'deonarayan@example.com',
  linkedin: 'https://linkedin.com/in/deonarayan',
  github: 'https://github.com/deonarayan',
};

export const skills = [
  'Azure DevOps',
  'Jenkins',
  'Kubernetes',
  'Terraform',
  'Docker',
  'Python',
  'Bash',
  'SonarQube',
  'JFrog Artifactory',
  'GitHub Actions',
  'AWS',
  'Prometheus',
];

export const experience = [
  {
    role: 'Cloud DevOps Engineer',
    company: 'Portfolio Labs',
    period: '2024 — Present',
    highlights: [
      'Designed multi-stage CI/CD pipelines with quality gates and artifact promotion',
      'Managed AKS workloads with Kustomize overlays for dev/staging/prod',
      'Authored Terraform modules for repeatable Azure landing zones',
    ],
  },
  {
    role: 'DevOps Engineer',
    company: 'Platform Team',
    period: '2022 — 2024',
    highlights: [
      'Migrated Jenkins jobs to declarative pipelines with shared libraries',
      'Implemented observability stack with Prometheus and Grafana dashboards',
      'Reduced deployment lead time by 40% through pipeline parallelization',
    ],
  },
];

export const projects = [
  {
    name: 'devops-cicd-tools-lab',
    description: 'Jenkins + Azure DevOps + JFrog + SonarQube integration with Flask sample app.',
    stack: ['Jenkins', 'Azure DevOps', 'JFrog', 'SonarQube', 'Python'],
    link: 'https://github.com/deonarayan/devops-cicd-tools-lab',
  },
  {
    name: 'devops-kubernetes-lab',
    description: 'Kustomize-based K8s delivery with dev/staging overlays and smoke tests.',
    stack: ['Kubernetes', 'Kustomize', 'Nginx Ingress'],
    link: 'https://github.com/deonarayan/devops-kubernetes-lab',
  },
  {
    name: 'devops-azure-lab',
    description: 'Terraform modules for Azure networking and App Service deployment.',
    stack: ['Azure', 'Terraform'],
    link: 'https://github.com/deonarayan/devops-azure-lab',
  },
  {
    name: 'devops-e2e-k8s-delivery',
    description: 'Helm-based AKS delivery pipeline with automated rollback.',
    stack: ['AKS', 'Helm', 'Azure DevOps'],
    link: 'https://github.com/deonarayan/devops-e2e-k8s-delivery',
  },
];

import { skills } from '../content/profile';

export default function Skills() {
  return (
    <section id="skills">
      <h2>Skills</h2>
      <ul className="tag-list">
        {skills.map((skill) => (
          <li key={skill}>{skill}</li>
        ))}
      </ul>
    </section>
  );
}

import { experience } from '../content/profile';

export default function Experience() {
  return (
    <section id="experience">
      <h2>Experience</h2>
      {experience.map((job) => (
        <article key={job.company} className="card">
          <h3>{job.role}</h3>
          <p className="muted">
            {job.company} · {job.period}
          </p>
          <ul>
            {job.highlights.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ul>
        </article>
      ))}
    </section>
  );
}

import { projects } from '../content/profile';

export default function Projects() {
  return (
    <section id="projects">
      <h2>Projects</h2>
      {projects.map((project) => (
        <article key={project.name} className="card">
          <h3>
            <a href={project.link} target="_blank" rel="noreferrer">
              {project.name}
            </a>
          </h3>
          <p>{project.description}</p>
          <ul className="tag-list">
            {project.stack.map((tech) => (
              <li key={tech}>{tech}</li>
            ))}
          </ul>
        </article>
      ))}
    </section>
  );
}

import { profile } from '../content/profile';

export default function Contact() {
  return (
    <section id="contact">
      <h2>Contact</h2>
      <p>
        <a href={`mailto:${profile.email}`}>{profile.email}</a>
      </p>
      <p>
        <a href={profile.linkedin} target="_blank" rel="noreferrer">
          LinkedIn
        </a>
        {' · '}
        <a href={profile.github} target="_blank" rel="noreferrer">
          GitHub
        </a>
      </p>
    </section>
  );
}

import Hero from './components/Hero';
import Skills from './components/Skills';
import Experience from './components/Experience';
import Projects from './components/Projects';
import Contact from './components/Contact';

export default function App() {
  return (
    <main className="container">
      <Hero />
      <Skills />
      <Experience />
      <Projects />
      <Contact />
    </main>
  );
}

import { profile } from '../content/profile';

export default function Hero() {
  return (
    <header>
      <p className="muted">{profile.location}</p>
      <h1>{profile.name}</h1>
      <h2 style={{ fontWeight: 400, color: '#94a3b8' }}>{profile.title}</h2>
      <p>{profile.summary}</p>
    </header>
  );
}

:root {
  font-family: Inter, system-ui, sans-serif;
  color: #e2e8f0;
  background: #0f172a;
  line-height: 1.6;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

a {
  color: #38bdf8;
}

.container {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

section {
  margin-bottom: 3rem;
}

section h2 {
  color: #38bdf8;
  border-bottom: 1px solid #334155;
  padding-bottom: 0.5rem;
  margin-bottom: 1.25rem;
}

.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  padding: 0;
}

.tag-list li {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 999px;
  padding: 0.25rem 0.75rem;
  font-size: 0.875rem;
}

.card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.card h3 {
  margin-top: 0;
  color: #f8fafc;
}

.muted {
  color: #94a3b8;
  font-size: 0.9rem;
}

{
  "name": "cloud-resume",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview",
    "lint": "tsc --noEmit"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@types/react": "^18.3.3",
    "@types/react-dom": "^18.3.0",
    "@vitejs/plugin-react": "^4.3.1",
    "typescript": "^5.5.4",
    "vite": "^5.4.2"
  }
}

{
  "buildCommand": "npm run build",
  "outputDirectory": "dist",
  "framework": "vite",
  "rewrites": [
    { "source": "/(.*)", "destination": "/index.html" }
  ]
}
